import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Bare Metal Cloud Upgrade/Downgrade Guide","description":"","frontmatter":{"title":"Bare Metal Cloud Upgrade/Downgrade Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-upgrade-downgrade-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-upgrade-downgrade-guide.md","lastUpdated":1794309341000}'),n={name:"operations-knowledge-base/baremetal/bare-metal-cloud-upgrade-downgrade-guide.md"};function i(d,e,s,l,g,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document explains the procedures and important considerations for upgrading or downgrading your Bare Metal Cloud server configuration, helping you complete configuration changes smoothly.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-before-you-begin" tabindex="-1">1. Before You Begin <a class="header-anchor" href="#_1-before-you-begin" aria-label="Permalink to &quot;1. Before You Begin&quot;">​</a></h2><p>Before performing an upgrade or downgrade, please read the following important information carefully.</p><h2 id="_1-1-prerequisites" tabindex="-1"><strong>1.1 Prerequisites</strong> <a class="header-anchor" href="#_1-1-prerequisites" aria-label="Permalink to &quot;**1.1 Prerequisites**&quot;">​</a></h2><ul><li>The server must be in the <strong>Paid</strong> status before an upgrade or downgrade can be performed.</li><li>After the upgrade or downgrade is completed, the server will automatically reboot. Please make sure to save your work and back up important data in advance to avoid service interruption or data loss.</li></ul><h2 id="_1-2-downgrade-refund-policy" tabindex="-1"><strong>1.2 Downgrade Refund Policy</strong> <a class="header-anchor" href="#_1-2-downgrade-refund-policy" aria-label="Permalink to &quot;**1.2 Downgrade Refund Policy**&quot;">​</a></h2><p>If you downgrade your server configuration during the current billing cycle, <strong>the price difference for the downgraded resources is non-refundable</strong>.</p><p>However, the server configuration and renewal price will be updated accordingly after the downgrade.</p><hr><h2 id="_2-upgrade-downgrade-procedure" tabindex="-1">2. Upgrade/Downgrade Procedure <a class="header-anchor" href="#_2-upgrade-downgrade-procedure" aria-label="Permalink to &quot;2. Upgrade/Downgrade Procedure&quot;">​</a></h2><h2 id="step-1-open-the-server-management-page" tabindex="-1"><strong>Step 1: Open the Server Management Page</strong> <a class="header-anchor" href="#step-1-open-the-server-management-page" aria-label="Permalink to &quot;**Step 1: Open the Server Management Page**&quot;">​</a></h2><ol><li>Log in to the Raksmart Client Area.</li><li>From the left navigation menu, select <strong>Products</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Locate the server you wish to upgrade or downgrade (make sure its status is <strong>Paid</strong>).</li><li>Click the product name to enter the server management page.</li></ol><hr><h2 id="step-2-open-the-upgrade-downgrade-page" tabindex="-1"><strong>Step 2: Open the Upgrade/Downgrade Page</strong> <a class="header-anchor" href="#step-2-open-the-upgrade-downgrade-page" aria-label="Permalink to &quot;**Step 2: Open the Upgrade/Downgrade Page**&quot;">​</a></h2><ol><li>On the server management page, click <strong>Upgrade/Downgrade</strong>.</li><li>The system will display the following notice:</li></ol><blockquote><p><strong>Notice</strong></p><p>If you downgrade your server configuration during the current billing cycle, the price difference for the downgraded resources is non-refundable. However, your renewal price and configuration will be adjusted accordingly.</p><p>For Bare Metal Cloud products, upgrading or downgrading the CPU, memory, or adding/removing Classic Network IP addresses will automatically reboot the server. Please back up your important data before proceeding.</p></blockquote><ol start="3"><li>After carefully reading the notice, click <strong>Confirm</strong> to enter the configuration page.</li></ol><hr><h2 id="step-3-select-the-configuration-to-change" tabindex="-1"><strong>Step 3: Select the Configuration to Change</strong> <a class="header-anchor" href="#step-3-select-the-configuration-to-change" aria-label="Permalink to &quot;**Step 3: Select the Configuration to Change**&quot;">​</a></h2><p>On the Upgrade/Downgrade page, you can adjust the following configuration items as needed:</p><ul><li><strong>Bandwidth</strong> – Select the desired bandwidth.</li><li><strong>Traffic</strong> – Select the required traffic plan.</li><li><strong>DDoS Protection</strong> – Available in selected locations only.</li><li><strong>IP Addresses</strong> – Standard IPs can be increased to a maximum of <strong>64</strong>.</li><li><strong>Memory (RAM)</strong> – Select the desired memory size.</li><li><strong>HDD Data Disk</strong> – Increase storage capacity.</li><li><strong>SSD Data Disk</strong> – Increase storage capacity. HDD and SSD data disks can be used simultaneously.</li></ul><hr><h2 id="step-4-confirm-and-submit" tabindex="-1"><strong>Step 4: Confirm and Submit</strong> <a class="header-anchor" href="#step-4-confirm-and-submit" aria-label="Permalink to &quot;**Step 4: Confirm and Submit**&quot;">​</a></h2><ol><li>After selecting the desired configuration, click <strong>Continue</strong>.</li><li>The system will generate the corresponding invoice(s).</li><li><strong>Note:</strong> If you upgrade multiple configuration items at the same time, each item will generate a separate invoice, and each invoice must be paid individually.</li><li>Once payment is completed, the server will automatically reboot and apply the new configuration.</li></ol><hr><h2 id="_3-view-the-updated-configuration" tabindex="-1">3. View the Updated Configuration <a class="header-anchor" href="#_3-view-the-updated-configuration" aria-label="Permalink to &quot;3. View the Updated Configuration&quot;">​</a></h2><p>After the upgrade or downgrade is completed, you can view the updated server configuration under the <strong>Configuration Options</strong> section on the server management page.</p><p>For more details, please refer to the <strong>Configuration Options</strong> section in the <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-control-panel-user-guide.html"><em>Bare Metal Cloud Control Panel Guide</em></a>.</p><hr><h2 id="_4-frequently-asked-questions" tabindex="-1">4. Frequently Asked Questions <a class="header-anchor" href="#_4-frequently-asked-questions" aria-label="Permalink to &quot;4. Frequently Asked Questions&quot;">​</a></h2><h2 id="q1-why-can-t-i-upgrade-the-cpu" tabindex="-1">Q1. Why can&#39;t I upgrade the CPU? <a class="header-anchor" href="#q1-why-can-t-i-upgrade-the-cpu" aria-label="Permalink to &quot;Q1. Why can&#39;t I upgrade the CPU?&quot;">​</a></h2><p><strong>A:</strong> The CPU is a core hardware component determined by the physical processor installed in the server and cannot be replaced after purchase.</p><p>If you require a more powerful CPU, we recommend purchasing a new server with the desired CPU configuration.</p><hr><h2 id="q2-why-can-t-i-change-the-network-line" tabindex="-1">Q2. Why can&#39;t I change the network line? <a class="header-anchor" href="#q2-why-can-t-i-change-the-network-line" aria-label="Permalink to &quot;Q2. Why can&#39;t I change the network line?&quot;">​</a></h2><p><strong>A:</strong> The network line is part of the server&#39;s underlying network architecture and routing configuration and cannot be changed after purchase.</p><p>If you need a different network line, please purchase a new server with the required network option.</p><hr><h2 id="q3-can-i-receive-a-refund-after-downgrading-my-configuration" tabindex="-1">Q3. Can I receive a refund after downgrading my configuration? <a class="header-anchor" href="#q3-can-i-receive-a-refund-after-downgrading-my-configuration" aria-label="Permalink to &quot;Q3. Can I receive a refund after downgrading my configuration?&quot;">​</a></h2><p><strong>A:</strong> No.</p><p>Downgrading during the current billing cycle does not qualify for a partial refund of the downgraded resources.</p><p>However, your renewal price will be adjusted based on the new configuration.</p><hr><h2 id="q4-will-upgrading-or-downgrading-affect-my-server" tabindex="-1">Q4. Will upgrading or downgrading affect my server? <a class="header-anchor" href="#q4-will-upgrading-or-downgrading-affect-my-server" aria-label="Permalink to &quot;Q4. Will upgrading or downgrading affect my server?&quot;">​</a></h2><p><strong>A:</strong> Yes.</p><p>The server will automatically reboot after the upgrade or downgrade is completed.</p><p>Please save your work and back up important data before proceeding. We also recommend performing the operation during off-peak hours to minimize service impact.</p><hr><h2 id="q5-why-can-t-i-see-a-specific-configuration-option-on-the-upgrade-downgrade-page" tabindex="-1">Q5. Why can&#39;t I see a specific configuration option on the Upgrade/Downgrade page? <a class="header-anchor" href="#q5-why-can-t-i-see-a-specific-configuration-option-on-the-upgrade-downgrade-page" aria-label="Permalink to &quot;Q5. Why can&#39;t I see a specific configuration option on the Upgrade/Downgrade page?&quot;">​</a></h2><p><strong>A:</strong> If a configuration item is not displayed on the Upgrade/Downgrade page, it means that item does not support upgrades or downgrades.</p><p>For example, <strong>CPU</strong>, <strong>system disk</strong>, and <strong>network line</strong> cannot be modified after purchase.</p><hr><h2 id="q6-can-i-upgrade-a-server-that-is-overdue-or-suspended" tabindex="-1">Q6. Can I upgrade a server that is overdue or suspended? <a class="header-anchor" href="#q6-can-i-upgrade-a-server-that-is-overdue-or-suspended" aria-label="Permalink to &quot;Q6. Can I upgrade a server that is overdue or suspended?&quot;">​</a></h2><p><strong>A:</strong> No.</p><p>The server must be in <strong>Paid</strong> status before an upgrade can be performed.</p><p>Please renew the server first, then proceed with the upgrade.</p>',59)])])}const h=r(n,[["render",i]]);export{c as __pageData,h as default};
